  "kd.sol5.category": "Commerce Électronique",
  "kd.sol5.desc": "Plateforme de commerce électronique gérée avec Rebase sur PostgreSQL pour vendre des produits et services en ligne avec catalogue, panier d'achat, passerelle de paiement et gestion des commandes.",
  "kd.sol5.feat1": "Catalogue de produits avec variantes, prix et images",
